import { Mesh, PlaneGeometry, Group, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  // --- Configuration ---
  const { scenePosition } = config;
  const pos = scenePosition || { x: 0, y: 1, z: 0.06 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };

  // --- Texture ---
  const texture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  texture.needsUpdate = true;

  // --- Plane material and geometry ---
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: 0xffffff,
  });
  const geometry = new PlaneGeometry(1.0, 0.3); // placeholder size; adjust as needed
  const plane = new Mesh(geometry, material);

  // --- Text (headline "Collection 2") ---
  // Use ctx.fontAtlas (MSDF text). Assume it returns a mesh or a function that creates one.
  const textOptions = {
    text: 'Collection 2',
    fontFamily: 'Lora', // display font
    fontWeight: 400,
    fontSize: 39 * 0.01, // scale to scene units (39px -> ~0.39 scene units? adjust)
    color: '#16161d', // ink color for contrast
    align: 'center',
    baseline: 'middle',
  };
  const textMesh = ctx.fontAtlas.createText(textOptions);
  // Position text centered on the plane, slightly in front
  textMesh.position.set(0, 0, 0.001);
  textMesh.scale.set(0.5, 0.5, 1); // scale down to fit; adjust based on actual size

  // --- Group everything ---
  const group = new Group();
  group.add(plane);
  group.add(textMesh);

  // --- Apply transforms ---
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // --- UserData ---
  group.userData.type = 'collection-card-2-label';
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    texture.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
